mapper.select:
select rule.RULE_ID ruleId, rule.RULE_NAME ruleName, rule.TARGET_TABLE targetTable, rule.FILE_PREFIX filePrefix, rule.SHEET_PREFIX sheetPrefix, rule.FILE_FINGERPRINT fileFingerprint, tableInfo.TARGET_TABLE_NAME targetTableName, tableInfo.IMP_HANDLE_SERVICE_NAME impHandleServiceName from EXCEL_IMPORT_RULE rule, EXCEL_IMPORT_TARGET_TABLE tableInfo where rule.TARGET_TABLE = tableInfo.TARGET_TABLE and tableInfo.STATUS = 'E' and rule.STATUS = 'E'
and rule.FILE_PREFIX is not null and rule.FILE_PREFIX != '' and #{impFileName,jdbcType=VARCHAR} like concat_ws('',rule.FILE_PREFIX , '%')
and rule.SHEET_PREFIX = #{impFileSheetName,jdbcType=VARCHAR}
